import Ajv from 'ajv';
import {ToolRegistry} from './registry.js';

describe('ToolRegistry', () => {
  it('returns a required-property rejection without invoking the executor', async () => {
    const registry = new ToolRegistry();
    const executor = jest.fn(async () => 'sunny');
    registry.register(
      {
        name: 'get_weather',
        description: 'Get weather for a location',
        inputSchema: {
          type: 'object',
          properties: {location: {type: 'string'}},
          required: ['location'],
        },
      },
      executor
    );

    const response = await registry.execute('get_weather', {});

    expect({
      namesRequiredLocation: /location.*required|required.*location/i.test(response.result),
      executorCalls: executor.mock.calls.length,
    }).toEqual({namesRequiredLocation: true, executorCalls: 0});
  });

  it('compiles a function-valued schema once when the same schema object is reused', async () => {
    const inputSchema = {type: 'object', properties: {}};
    const registry = new ToolRegistry();
    const compile = jest.spyOn(Ajv.prototype, 'compile');
    registry.register(
      () => ({name: 'dynamic_tool', description: 'Dynamic schema', inputSchema}),
      async () => 'ok'
    );

    await registry.execute('dynamic_tool', {});
    await registry.execute('dynamic_tool', {});

    expect(compile).toHaveBeenCalledTimes(1);
    compile.mockRestore();
  });
});
